-- app/migrations/2026-11-28_task_seed_6.sql: one Work-queue ticket per agent (0180's 30 roles after the Founder and the CEO, and the 12
-- advocates), each its own release, in the CEO's wave order (Jason, 2026-11-28). task-seed-5's four team group tickets are withdrawn.
-- Data only, no CREATE, nothing deleted. Every id named (MAX(id)+1, guarded by NOT EXISTS). A ticket is made only where its goal
-- exists and no ticket has its (gauge, item). A withdrawn ticket is kept, and only withdrawn while still as task-seed-5 wrote it.
SET @n = (SELECT COALESCE(MAX(id), 0) + 1 FROM control_gauge_tasks);
SET @p = (SELECT id FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:goals' AND item = 'The transition cutover: our business and conversations on the platform by Dec 15' ORDER BY id LIMIT 1);
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, rel, priority, ticket, stage, stage_at, parent_id) SELECT @n, UTC_TIMESTAMP(), '', 'area:transition', 'Agent online 01 (wave 1): Project Manager (8), upgraded in place', 'fix', 'Agent online 01 (wave 1): Project Manager (8), upgraded in place', 'task', '', 'task-seed-6 (Build & QA, 21)', 0, 'Being built by the batch (jobs 18, 18b, 18c, 21). Jason, 2026-11-28: "Bring each one online individually… just in case we run out of usage". Its own release, on staging''s runner per 0179, stage ceiling and fences unchanged. Active today: upgraded in place. Live only once its Run a test ticket passes on /admin/config/team', 'research/ai-results/job18-team/team-middle-managers.md · decisions/0180 appendix · handoffs/piece2-team.md', '', 1, 'work', 'planning', UTC_TIMESTAMP(), @p FROM DUAL WHERE @p IS NOT NULL AND NOT EXISTS (SELECT id FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:transition' AND item = 'Agent online 01 (wave 1): Project Manager (8), upgraded in place' ORDER BY id LIMIT 1);
